 67|   recordHarvest(
 68|     memberId: string | undefined,
 69|     hiveId: string,
 70|     input: { date?: unknown; kilograms?: unknown },
 71|   ): Harvest {
 72|     const ownerId = requireMember(memberId);
 73|     const hive = this.findHive(hiveId);
 74|     if (hive.ownerId !== ownerId) {
 75|       throw new DomainError("forbidden", "Only the hive owner can record harvests");
 76|     }
 77|     const date = requireDate(input.date);
